1	package com.example.starter.incident;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.Clock;
7	import java.time.Instant;
8	import java.time.temporal.ChronoUnit;
9	import java.util.ArrayList;
10	import java.util.EnumSet;
11	import java.util.HexFormat;
12	import java.util.List;
13	import java.util.Map;
14	import java.util.Set;
15	import java.util.function.Supplier;
16	
17	import com.example.starter.incident.dto.Requests.ActionRequest;
18	import com.example.starter.incident.dto.Requests.EscalationAckRequest;
19	import com.example.starter.incident.dto.Requests.EscalationCheckRequest;
20	import com.example.starter.incident.dto.Requests.ReportRequest;
21	import com.example.starter.incident.dto.Requests.StatusRequest;
22	import com.example.starter.incident.dto.Requests.TakeoverRequest;
23	import com.example.starter.incident.dto.Requests.TaskActionRequest;
24	import com.example.starter.incident.dto.Requests.TaskCreateRequest;
25	import com.example.starter.incident.dto.Requests.TransferAcceptRequest;
26	import com.example.starter.incident.dto.Requests.TransferRequest;
27	import com.example.starter.incident.dto.Responses.ActionView;
28	import com.example.starter.incident.dto.Responses.EscalationHistoryView;
29	import com.example.starter.incident.dto.Responses.EscalationView;
30	import com.example.starter.incident.dto.Responses.HistoryView;
31	import com.example.starter.incident.dto.Responses.IncidentTasksView;
32	import com.example.starter.incident.dto.Responses.IncidentView;
33	import com.example.starter.incident.dto.Responses.StatusChangeView;
34	import com.example.starter.incident.dto.Responses.TaskBlockerView;
35	import com.example.starter.incident.dto.Responses.TaskView;
36	import com.example.starter.incident.dto.Responses.TransferView;
37	import com.example.starter.incident.dto.Responses.UnfinishedTaskView;
38	import com.fasterxml.jackson.core.JsonProcessingException;
39	import com.fasterxml.jackson.databind.ObjectMapper;
40	import org.springframework.dao.DuplicateKeyException;
41	import org.springframework.stereotype.Service;
42	import org.springframework.transaction.annotation.Transactional;
43	
44	/**
45	 * 事件指挥核心服务。
46	 * 并发约定：所有写接口先 SELECT ... FOR UPDATE 锁定事件行，同事务内完成
47	 * 幂等键占位、业务校验与写入，保证并发请求按事务提交顺序生效。
48	 * 幂等约定：commandKey 全局唯一，同键同参重放首次响应，同键改参返回 409。
49	 * 遏制期限：首次进入 COMMANDING 时以该次接管 UTC 时刻按等级确定
50	 * （S1=5分钟、S2=15分钟、S3=60分钟、S4=240分钟），交接不重置。
51	 */
52	@Service
53	public class IncidentService {
54	
55	    private static final String SEP = "\\u001F";
56	
57	    /** 各严重等级的遏制时限（分钟），等级沿用上报值且不可修改。 */
58	    private static final Map<String, Long> CONTAINMENT_MINUTES = Map.of(
59	            "S1", 5L, "S2", 15L, "S3", 60L, "S4", 240L);
60	
61	    /** 每事件处置任务上限。 */
62	    private static final int MAX_TASKS_PER_INCIDENT = 20;
63	
64	    /** 每任务阻塞事件上限。 */
65	    private static final int MAX_BLOCKERS_PER_TASK = 5;
66	
67	    /** 视为阻塞已解除的目标事件状态。 */
68	    private static final Set<IncidentStatus> UNBLOCKING_STATUSES = EnumSet.of(
69	            IncidentStatus.CONTAINED, IncidentStatus.RESOLVED, IncidentStatus.CLOSED);
70	
71	    private final IncidentRepository incidents;
72	    private final EscalationRepository escalations;
73	    private final IncidentTaskRepository tasks;
74	    private final CommandKeyRepository commandKeys;
75	    private final ObjectMapper objectMapper;
76	    private final Clock clock;
77	
78	    public IncidentService(IncidentRepository incidents, EscalationRepository escalations,
79	                           IncidentTaskRepository tasks, CommandKeyRepository commandKeys,
80	                           ObjectMapper objectMapper, Clock clock) {
81	        this.incidents = incidents;
82	        this.escalations = escalations;
83	        this.tasks = tasks;
84	        this.commandKeys = commandKeys;
85	        this.objectMapper = objectMapper;
86	        this.clock = clock;
87	    }
88	
89	    private Instant now() {
90	        return clock.instant();
91	    }
92	
93	    /**
94	     * 事件上报：初始状态 REPORTED，无指挥人。incidentKey 重复返回 409。
95	     */
96	    @Transactional
97	    public IncidentView report(ReportRequest req) {
98	        String incidentKey = requireText(req.incidentKey(), "incidentKey");
99	        String severity = requireText(req.severity(), "severity");
100	        if (!severity.matches("S[1-4]")) {
101	            throw ApiException.badRequest("severity 必须为 S1~S4");
102	        }
103	        String summary = requireText(req.summary(), "summary");
104	        String reporter = requireText(req.reporter(), "reporter");
105	        if (incidents.findByKey(incidentKey).isPresent()) {
106	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
107	        }
108	        Instant now = now();
109	        Incident incident = new Incident(0L, incidentKey, severity, summary, reporter,
110	                IncidentStatus.REPORTED, null, now, now, null);
111	        long id;
112	        try {
113	            id = incidents.insert(incident);
114	        } catch (DuplicateKeyException e) {
115	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
116	        }
117	        incidents.insertStatusChange(new StatusChange(0L, id, null, IncidentStatus.REPORTED, reporter, now));
118	        return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
119	    }
120	
121	    /**
122	     * 首次接管：REPORTED → COMMANDING，记录当前指挥人，
123	     * 并以该次接管 UTC 时刻按等级确定遏制期限（只写一次，交接不重置）。
124	     */
125	    @Transactional
126	    public IncidentView takeover(String incidentKey, String actor, TakeoverRequest req) {
127	        String commandKey = requireText(req.commandKey(), "commandKey");
128	        Incident incident = lockIncident(incidentKey);
129	        return runIdempotent(commandKey, "takeover", hash(incidentKey, actor), IncidentView.class,
130	                () -> {
131	                    if (incident.status() != IncidentStatus.REPORTED) {
132	                        throw ApiException.illegalTransition(
133	                                "仅 REPORTED 状态可接管，当前状态: " + incident.status());
134	                    }
135	                    Instant now = now();
136	                    Instant deadline = now.plus(CONTAINMENT_MINUTES.get(incident.severity()),
137	                            ChronoUnit.MINUTES);
138	                    incidents.updateState(incident.id(), IncidentStatus.COMMANDING, actor, now);
139	                    incidents.updateDeadline(incident.id(), deadline, now);
140	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
141	                            IncidentStatus.REPORTED, IncidentStatus.COMMANDING, actor, now));
142	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
143	                });
144	    }
145	
146	    /**
147	     * 发起交接：仅当前指挥人可发起，目标人必须不同；RESOLVED/CLOSED 禁止发起。
148	     */
149	    @Transactional
150	    public TransferView initiateTransfer(String incidentKey, String actor, TransferRequest req) {
151	        String commandKey = requireText(req.commandKey(), "commandKey");
152	        String toCommander = requireText(req.toCommander(), "toCommander");
153	        Incident incident = lockIncident(incidentKey);
154	        return runIdempotent(commandKey, "transfer_initiate", hash(incidentKey, actor, toCommander),
155	                TransferView.class, () -> {
156	                    requireCommander(incident, actor);
157	                    if (incident.status() == IncidentStatus.RESOLVED
158	                            || incident.status() == IncidentStatus.CLOSED) {
159	                        throw ApiException.illegalTransition(
160	                                incident.status() + " 状态不允许发起交接");
161	                    }
162	                    if (incident.status() == IncidentStatus.REPORTED) {
163	                        throw ApiException.illegalTransition("尚未接管的事件不能发起交接");
164	                    }
165	                    if (toCommander.equals(incident.commander())) {
166	                        throw ApiException.badRequest("目标指挥人必须与当前指挥人不同");
167	                    }
168	                    if (incidents.findPendingTransfer(incident.id()).isPresent()) {
169	                        throw ApiException.conflict("已存在待接受的交接，不能重复发起");
170	                    }
171	                    Instant now = now();
172	                    incidents.insertTransfer(new IncidentTransfer(0L, incident.id(),
173	                            incident.commander(), toCommander, TransferStatus.PENDING, now, null));
174	                    return toTransferView(incidents.findPendingTransfer(incident.id()).orElseThrow());
175	                });
176	    }
177	
178	    /**
179	     * 接受交接：仅待接受目标人可接受；接受后原子切换当前指挥人。
180	     * RESOLVED/CLOSED 禁止接受；待接受期间目标人无其他操作权限。
181	     */
182	    @Transactional
183	    public IncidentView acceptTransfer(String incidentKey, String actor, TransferAcceptRequest req) {
184	        String commandKey = requireText(req.commandKey(), "commandKey");
185	        Incident incident = lockIncident(incidentKey);
186	        return runIdempotent(commandKey, "transfer_accept", hash(incidentKey, actor), IncidentView.class,
187	                () -> {
188	                    if (incident.status() == IncidentStatus.RESOLVED
189	                            || incident.status() == IncidentStatus.CLOSED) {
190	                        throw ApiException.illegalTransition(
191	                                incident.status() + " 状态不允许接受交接");
192	                    }
193	                    IncidentTransfer pending = incidents.findPendingTransfer(incident.id())
194	                            .orElseThrow(() -> ApiException.conflict("当前没有待接受的交接"));
195	                    if (!pending.toCommander().equals(actor)) {
196	                        throw ApiException.conflict("只有交接目标人 " + pending.toCommander() + " 能接受交接");
197	                    }
198	                    Instant now = now();
199	                    incidents.acceptTransfer(pending.id(), now);
200	                    incidents.updateState(incident.id(), incident.status(), pending.toCommander(), now);
201	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
202	                });
203	    }
204	
205	    /**
206	     * 追加处置记录：仅当前指挥人可写；CLOSED 后禁止写入。
207	     * actionKey 事件内唯一：同键同内容幂等返回首次记录，同键不同内容返回 409。
208	     */
209	    @Transactional
210	    public ActionView addAction(String incidentKey, String actor, ActionRequest req) {
211	        String commandKey = requireText(req.commandKey(), "commandKey");
212	        String actionKey = requireText(req.actionKey(), "actionKey");
213	        String actionType = requireText(req.actionType(), "actionType");
214	        String note = requireText(req.note(), "note");
215	        if (req.occurredAt() == null) {
216	            throw ApiException.badRequest("occurredAt 不能为空");
217	        }
218	        Instant occurredAt = req.occurredAt().truncatedTo(ChronoUnit.MICROS);
219	        Incident incident = lockIncident(incidentKey);
220	        return runIdempotent(commandKey, "action",
221	                hash(incidentKey, actor, actionKey, actionType, note, occurredAt.toString()),
222	                ActionView.class, () -> {
223	                    requireCommander(incident, actor);
224	                    if (incident.status() == IncidentStatus.CLOSED) {
225	                        throw ApiException.illegalTransition("事件已关闭，不能再追加处置记录");
226	                    }
227	                    var existing = incidents.findAction(incident.id(), actionKey);
228	                    if (existing.isPresent()) {
229	                        IncidentAction found = existing.get();
230	                        if (!found.sameContent(actionType, note, occurredAt)) {
231	                            throw ApiException.conflict("actionKey 已被不同内容使用: " + actionKey);
232	                        }
233	                        return toActionView(found);
234	                    }
235	                    Instant now = now();
236	                    incidents.insertAction(new IncidentAction(0L, incident.id(), actionKey, actionType,
237	                            note, occurredAt, actor, now));
238	                    return toActionView(incidents.findAction(incident.id(), actionKey).orElseThrow());
239	                });
240	    }
241	
242	    /**
243	     * 状态变更：仅当前指挥人可操作，仅允许 COMMANDING→CONTAINED→RESOLVED→CLOSED 逐级前进。
244	     * 进入 CONTAINED 时同事务将仍 OPEN 的逾期升级记录原子置为 CANCELLED，已确认记录保留。
245	     */
246	    @Transactional
247	    public IncidentView changeStatus(String incidentKey, String actor, StatusRequest req) {
248	        String commandKey = requireText(req.commandKey(), "commandKey");
249	        String target = requireText(req.targetStatus(), "targetStatus");
250	        IncidentStatus targetStatus;
251	        try {
252	            targetStatus = IncidentStatus.valueOf(target);
253	        } catch (IllegalArgumentException e) {
254	            throw ApiException.badRequest("未知目标状态: " + target);
255	        }
256	        Incident incident = lockIncident(incidentKey);
257	        return runIdempotent(commandKey, "status", hash(incidentKey, actor, target),
258	                IncidentView.class, () -> {
259	                    requireCommander(incident, actor);
260	                    IncidentStatus next = incident.status().next();
261	                    if (next == null || next != targetStatus) {
262	                        throw ApiException.illegalTransition(
263	                                "不允许从 " + incident.status() + " 流转到 " + targetStatus);
264	                    }
265	                    if (targetStatus == IncidentStatus.RESOLVED) {
266	                        // 解决门禁：全部处置任务进入 DONE/CANCELLED 后才可解决
267	                        List<UnfinishedTaskView> unfinished = tasks
268	                                .listOpenByIncident(incident.id()).stream()
269	                                .map(t -> new UnfinishedTaskView(t.groupCode(), t.taskKey()))
270	                                .toList();
271	                        if (!unfinished.isEmpty()) {
272	                            throw ApiException.conflict(
273	                                    "仍有未完成的处置任务，不能进入 RESOLVED", unfinished);
274	                        }
275	                    }
276	                    Instant now = now();
277	                    incidents.updateState(incident.id(), targetStatus, incident.commander(), now);
278	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
279	                            incident.status(), targetStatus, actor, now));
280	                    if (targetStatus == IncidentStatus.CONTAINED) {
281	                        escalations.cancelOpenForIncident(incident.id(), now);
282	                    }
283	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
284	                });
285	    }
286	
287	    /**
288	     * 单事件遏制逾期检查：以注入 Clock 的当前时刻评估，不做定时扫描。
289	     * 仅当事件仍为 COMMANDING、尚无升级记录且当前时刻 ≥ 接管时确定的期限时，
290	     * 追加一条 OPEN 记录（保存期限、触发时刻、当时指挥人），每事件至多一条。
291	     * 期限前或其他状态不产生记录；同键重放首次结果（含期限前的无记录结果），
292	     * 失败不占键；需要重新评估必须更换 commandKey。
293	     */
294	    @Transactional
295	    public EscalationHistoryView checkEscalation(String incidentKey, EscalationCheckRequest req) {
296	        String commandKey = requireText(req.commandKey(), "commandKey");
297	        Incident incident = lockIncident(incidentKey);
298	        return runIdempotent(commandKey, "escalation_check", hash(incidentKey),
299	                EscalationHistoryView.class, () -> {
300	                    var existing = escalations.findByIncident(incident.id());
301	                    if (existing.isPresent()) {
302	                        return toEscalationHistory(incident, List.of(existing.get()));
303	                    }
304	                    Instant currentTime = now();
305	                    if (incident.status() == IncidentStatus.COMMANDING
306	                            && incident.deadlineAt() != null
307	                            && !currentTime.isBefore(incident.deadlineAt())) {
308	                        escalations.insert(new Escalation(0L, incident.id(), incident.deadlineAt(),
309	                                currentTime, incident.commander(), EscalationStatus.OPEN,
310	                                null, null, null, currentTime, currentTime));
311	                    }
312	                    return toEscalationHistory(incident,
313	                            escalations.listByIncident(incident.id()));
314	                });
315	    }
316	
317	    /**
318	     * 确认 OPEN 升级记录：仅操作当时的当前指挥人可确认（待接受期间目标人无确认权，
319	     * 交接接受后旧指挥人失去确认权），提交非空处置说明后进入 ACKNOWLEDGED，
320	     * 记录确认人与 UTC 时刻。已 CANCELLED/ACKNOWLEDGED 或不存在记录均为 409。
321	     */
322	    @Transactional
323	    public EscalationView acknowledgeEscalation(String incidentKey, String actor,
324	                                                EscalationAckRequest req) {
325	        String commandKey = requireText(req.commandKey(), "commandKey");
326	        String note = requireText(req.note(), "note");
327	        Incident incident = lockIncident(incidentKey);
328	        return runIdempotent(commandKey, "escalation_ack", hash(incidentKey, actor, note),
329	                EscalationView.class, () -> {
330	                    requireCommander(incident, actor);
331	                    Escalation escalation = escalations.findByIncident(incident.id())
332	                            .orElseThrow(() -> ApiException.conflict("当前没有可确认的升级记录"));
333	                    if (escalation.status() != EscalationStatus.OPEN) {
334	                        throw ApiException.conflict(
335	                                "升级记录状态为 " + escalation.status() + "，不能确认");
336	                    }
337	                    Instant ackedAt = now();
338	                    int updated = escalations.acknowledge(escalation.id(), note, actor, ackedAt);
339	                    if (updated == 0) {
340	                        throw ApiException.conflict("升级记录已被并发处理，不能确认");
341	                    }
342	                    return toEscalationView(
343	                            escalations.findByIncident(incident.id()).orElseThrow());
344	                });
345	    }
346	
347	    /**
348	     * 查询事件当前状态（含当前指挥人与待接受交接目标人）。只读，不隐式写入。
349	     */
350	    @Transactional(readOnly = true)
351	    public IncidentView get(String incidentKey) {
352	        Incident incident = incidents.findByKey(incidentKey)
353	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
354	        String pendingTo = incidents.findPendingTransfer(incident.id())
355	                .map(IncidentTransfer::toCommander).orElse(null);
356	        return toView(incident, pendingTo);
357	    }
358	
359	    /**
360	     * 查询遏制期限、当前升级及完整升级历史；只读，不隐式写入。
361	     */
362	    @Transactional(readOnly = true)
363	    public EscalationHistoryView escalationHistory(String incidentKey) {
364	        Incident incident = incidents.findByKey(incidentKey)
365	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
366	        return toEscalationHistory(incident, escalations.listByIncident(incident.id()));
367	    }
368	
369	    /**
370	     * 查询完整历史：事件本体、状态流转、处置记录、交接记录、升级记录。
371	     */
372	    @Transactional(readOnly = true)
373	    public HistoryView history(String incidentKey) {
374	        Incident incident = incidents.findByKey(incidentKey)
375	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
376	        String pendingTo = incidents.findPendingTransfer(incident.id())
377	                .map(IncidentTransfer::toCommander).orElse(null);
378	        List<StatusChangeView> statusHistory = incidents.listStatusHistory(incident.id()).stream()
379	                .map(s -> new StatusChangeView(
380	                        s.fromStatus() == null ? null : s.fromStatus().name(),
381	                        s.toStatus().name(), s.actor(), s.occurredAt()))
382	                .toList();
383	        List<ActionView> actions = incidents.listActions(incident.id()).stream()
384	                .map(this::toActionView).toList();
385	        List<TransferView> transfers = incidents.listTransfers(incident.id()).stream()
386	                .map(IncidentService::toTransferView).toList();
387	        List<EscalationView> escalationList = escalations.listByIncident(incident.id()).stream()
388	                .map(this::toEscalationView).toList();
389	        return new HistoryView(toView(incident, pendingTo), statusHistory, actions, transfers,
390	                escalationList);
391	    }
392	
393	    /**
394	     * 创建处置任务：仅当前指挥人；taskKey 事件内唯一；阻塞事件 0~5 个、必须存在且非自身；
395	     * 创建时在依赖图全局锁内做环检测，拒绝直接或间接环（409 且不留部分任务或边）。
396	     * taskKey 幂等：同键同内容（含阻塞集合）返回首次任务，同键不同内容返回 409。
397	     */
398	    @Transactional
399	    public TaskView createTask(String incidentKey, String actor, TaskCreateRequest req) {
400	        String commandKey = requireText(req.commandKey(), "commandKey");
401	        String taskKey = requireText(req.taskKey(), "taskKey");
402	        String groupCode = requireText(req.groupCode(), "groupCode");
403	        String title = requireText(req.title(), "title");
404	        List<String> blockerKeys = req.blockerIncidentKeys() == null ? List.of()
405	                : req.blockerIncidentKeys().stream()
406	                        .map(k -> requireText(k, "blockerIncidentKey"))
407	                        .distinct()
408	                        .toList();
409	        if (blockerKeys.size() > MAX_BLOCKERS_PER_TASK) {
410	            throw ApiException.badRequest("阻塞事件最多 " + MAX_BLOCKERS_PER_TASK + " 个");
411	        }
412	        if (blockerKeys.contains(incidentKey)) {
413	            throw ApiException.badRequest("阻塞事件不能是事件自身: " + incidentKey);
414	        }
415	        Incident incident = lockIncident(incidentKey);
416	        return runIdempotent(commandKey, "task_create",
417	                hash(incidentKey, actor, taskKey, groupCode, title, String.join(",", blockerKeys)),
418	                TaskView.class, () -> {
419	                    requireCommander(incident, actor);
420	                    if (incident.status() == IncidentStatus.CLOSED) {
421	                        throw ApiException.illegalTransition("事件已关闭，不能再创建处置任务");
422	                    }
423	                    var existing = tasks.findByKey(incident.id(), taskKey);
424	                    if (existing.isPresent()) {
425	                        IncidentTask found = existing.get();
426	                        List<String> existingBlockers = incidents.listBlockingIncidents(found.id())
427	                                .stream().map(Incident::incidentKey).sorted().toList();
428	                        List<String> requested = blockerKeys.stream().sorted().toList();
429	                        if (!found.sameContent(groupCode, title)
430	                                || !existingBlockers.equals(requested)) {
431	                            throw ApiException.conflict("taskKey 已被不同内容使用: " + taskKey);
432	                        }
433	                        return toTaskView(found);
434	                    }
435	                    if (tasks.countByIncident(incident.id()) >= MAX_TASKS_PER_INCIDENT) {
436	                        throw ApiException.conflict("每个事件最多创建 " + MAX_TASKS_PER_INCIDENT
437	                                + " 个处置任务");
438	                    }
439	                    List<Incident> blockers = new ArrayList<>();
440	                    for (String blockerKey : blockerKeys) {
441	                        blockers.add(incidents.findByKey(blockerKey)
442	                                .orElseThrow(() -> ApiException.notFound(
443	                                        "阻塞事件不存在: " + blockerKey)));
444	                    }
445	                    // 全局图锁：串行化环检测与边写入，并发反向依赖下最终图无环
446	                    tasks.lockGraph();
447	                    for (Incident blocker : blockers) {
448	                        if (tasks.isReachable(blocker.id(), incident.id())) {
449	                            throw ApiException.conflict("阻塞关系会形成环: "
450	                                    + blocker.incidentKey() + " 已直接或间接依赖 " + incidentKey);
451	                        }
452	                    }
453	                    Instant now = now();
454	                    long taskId = tasks.insert(new IncidentTask(0L, incident.id(), taskKey,
455	                            groupCode, title, TaskStatus.OPEN, actor, null, null, null, null,
456	                            now, now));
457	                    for (Incident blocker : blockers) {
458	                        tasks.insertBlocker(taskId, blocker.id(), now);
459	                    }
460	                    return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
461	                });
462	    }
463	
464	    /**
465	     * 完成任务：仅当前指挥人；仅 OPEN 可完成；全部阻塞事件进入
466	     * CONTAINED/RESOLVED/CLOSED 后才可完成，否则 409 并返回未解除事件列表。
467	     * DONE/CANCELLED 为终态，重复操作按 commandKey 幂等规则返回首次结果。
468	     */
469	    @Transactional
470	    public TaskView completeTask(String incidentKey, String taskKey, String actor,
471	                                 TaskActionRequest req) {
472	        String commandKey = requireText(req.commandKey(), "commandKey");
473	        Incident incident = lockIncident(incidentKey);
474	        return runIdempotent(commandKey, "task_complete", hash(incidentKey, taskKey, actor),
475	                TaskView.class, () -> {
476	                    requireCommander(incident, actor);
477	                    IncidentTask task = tasks.findByKey(incident.id(), taskKey)
478	                            .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
479	                    if (task.status() != TaskStatus.OPEN) {
480	                        throw ApiException.conflict(
481	                                "任务已处于终态 " + task.status() + "，不能完成");
482	                    }
483	                    List<String> unresolved = unresolvedBlockers(task.id());
484	                    if (!unresolved.isEmpty()) {
485	                        throw ApiException.conflict("存在未解除阻塞的事件: "
486	                                + String.join(",", unresolved), List.copyOf(unresolved));
487	                    }
488	                    tasks.markDone(task.id(), actor, now());
489	                    return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
490	                });
491	    }
492	
493	    /**
494	     * 取消任务：仅当前指挥人；仅 OPEN 可取消；DONE/CANCELLED 为终态，
495	     * 重复操作按 commandKey 幂等规则返回首次结果。
496	     */
497	    @Transactional
498	    public TaskView cancelTask(String incidentKey, String taskKey, String actor,
499	                               TaskActionRequest req) {
500	        String commandKey = requireText(req.commandKey(), "commandKey");
501	        Incident incident = lockIncident(incidentKey);
502	        return runIdempotent(commandKey, "task_cancel", hash(incidentKey, taskKey, actor),
503	                TaskView.class, () -> {
504	                    requireCommander(incident, actor);
505	                    IncidentTask task = tasks.findByKey(incident.id(), taskKey)
506	                            .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
507	                    if (task.status() != TaskStatus.OPEN) {
508	                        throw ApiException.conflict(
509	                                "任务已处于终态 " + task.status() + "，不能取消");
510	                    }
511	                    tasks.markCancelled(task.id(), actor, now());
512	                    return toTaskView(tasks.findByKey(incident.id(), taskKey).orElseThrow());
513	                });
514	    }
515	
516	    /**
517	     * 按事件分组查询任务（含阻塞状态，按目标事件当前状态计算）。只读，不隐式写入。
518	     */
519	    @Transactional(readOnly = true)
520	    public IncidentTasksView listTasks(String incidentKey) {
521	        Incident incident = incidents.findByKey(incidentKey)
522	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
523	        List<TaskView> views = tasks.listByIncident(incident.id()).stream()
524	                .map(this::toTaskView).toList();
525	        return new IncidentTasksView(incident.incidentKey(), views);
526	    }
527	
528	    /**
529	     * 查询单任务明细（含阻塞状态）。只读，不隐式写入。
530	     */
531	    @Transactional(readOnly = true)
532	    public TaskView getTask(String incidentKey, String taskKey) {
533	        Incident incident = incidents.findByKey(incidentKey)
534	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
535	        IncidentTask task = tasks.findByKey(incident.id(), taskKey)
536	                .orElseThrow(() -> ApiException.notFound("任务不存在: " + taskKey));
537	        return toTaskView(task);
538	    }
539	
540	    /**
541	     * 仍未解除阻塞的事件键列表：目标事件未进入 CONTAINED/RESOLVED/CLOSED 即未解除。
542	     */
543	    private List<String> unresolvedBlockers(long taskId) {
544	        return incidents.listBlockingIncidents(taskId).stream()
545	                .filter(b -> !UNBLOCKING_STATUSES.contains(b.status()))
546	                .map(Incident::incidentKey)
547	                .toList();
548	    }
549	
550	    private Incident lockIncident(String incidentKey) {
551	        requireText(incidentKey, "incidentKey");
552	        return incidents.lockByKey(incidentKey)
553	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
554	    }
555	
556	    private static void requireCommander(Incident incident, String actor) {
557	        if (incident.commander() == null || !incident.commander().equals(actor)) {
558	            throw ApiException.conflict("只有当前指挥人 "
559	                    + (incident.commander() == null ? "(无)" : incident.commander()) + " 能执行该操作");
560	        }
561	    }
562	
563	    private static String requireText(String value, String field) {
564	        if (value == null || value.isBlank()) {
565	            throw ApiException.badRequest(field + " 不能为空");
566	        }
567	        return value.strip();
568	    }
569	
570	    /**
571	     * 幂等执行：同键同参重放首次响应，同键改参 409；并发同键由唯一约束串行化。
572	     */
573	    private <T> T runIdempotent(String commandKey, String operation, String requestHash,
574	                                Class<T> type, Supplier<T> business) {
575	        var existing = commandKeys.find(commandKey);
576	        if (existing.isPresent()) {
577	            return replay(existing.get(), operation, requestHash, type);
578	        }
579	        try {
580	            commandKeys.insertPlaceholder(commandKey, operation, requestHash, now());
581	        } catch (DuplicateKeyException e) {
582	            var committed = commandKeys.findForUpdate(commandKey)
583	                    .orElseThrow(() -> ApiException.conflict("commandKey 处理冲突: " + commandKey));
584	            return replay(committed, operation, requestHash, type);
585	        }
586	        T result = business.get();
587	        commandKeys.fillResponse(commandKey, 200, toJson(result));
588	        return result;
589	    }
590	
591	    private <T> T replay(CommandKeyRecord record, String operation, String requestHash, Class<T> type) {
592	        if (!record.operation().equals(operation) || !record.requestHash().equals(requestHash)) {
593	            throw ApiException.conflict("commandKey 已被不同参数的请求使用: " + record.commandKey());
594	        }
595	        if (record.responseBody() == null) {
596	            throw ApiException.conflict("commandKey 正在处理中: " + record.commandKey());
597	        }
598	        try {
599	            return objectMapper.readValue(record.responseBody(), type);
600	        } catch (JsonProcessingException e) {
601	            throw new IllegalStateException("幂等响应反序列化失败", e);
602	        }
603	    }
604	
605	    private String toJson(Object value) {
606	        try {
607	            return objectMapper.writeValueAsString(value);
608	        } catch (JsonProcessingException e) {
609	            throw new IllegalStateException("响应序列化失败", e);
610	        }
611	    }
612	
613	    private static String hash(String... parts) {
614	        try {
615	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
616	            byte[] out = digest.digest(String.join(SEP, parts).getBytes(StandardCharsets.UTF_8));
617	            return HexFormat.of().formatHex(out);
618	        } catch (NoSuchAlgorithmException e) {
619	            throw new IllegalStateException(e);
620	        }
621	    }
622	
623	    private IncidentView toView(Incident incident, String pendingTransferTo) {
624	        return new IncidentView(incident.incidentKey(), incident.severity(), incident.summary(),
625	                incident.reporter(), incident.status().name(), incident.commander(), pendingTransferTo,
626	                incident.createdAt(), incident.updatedAt(), incident.deadlineAt());
627	    }
628	
629	    private ActionView toActionView(IncidentAction action) {
630	        return new ActionView(action.actionKey(), action.actionType(), action.note(),
631	                action.occurredAt(), action.actor(), action.createdAt());
632	    }
633	
634	    /**
635	     * 组装任务视图：阻塞状态按目标事件查询时的当前状态计算，不写回依赖任务。
636	     */
637	    private TaskView toTaskView(IncidentTask task) {
638	        List<TaskBlockerView> blockers = incidents.listBlockingIncidents(task.id()).stream()
639	                .map(b -> new TaskBlockerView(b.incidentKey(), b.status().name(),
640	                        UNBLOCKING_STATUSES.contains(b.status())))
641	                .toList();
642	        return new TaskView(task.taskKey(), task.groupCode(), task.title(), task.status().name(),
643	                blockers, task.createdBy(), task.createdAt(), task.doneBy(), task.doneAt(),
644	                task.cancelledBy(), task.cancelledAt());
645	    }
646	
647	    private static TransferView toTransferView(IncidentTransfer transfer) {
648	        return new TransferView(transfer.id(), transfer.fromCommander(), transfer.toCommander(),
649	                transfer.status().name(), transfer.createdAt(), transfer.acceptedAt());
650	    }
651	
652	    private EscalationView toEscalationView(Escalation escalation) {
653	        return new EscalationView(escalation.id(), escalation.deadlineAt(), escalation.triggeredAt(),
654	                escalation.triggeredCommander(), escalation.status().name(), escalation.note(),
655	                escalation.acknowledgedBy(), escalation.acknowledgedAt(), escalation.createdAt());
656	    }
657	
658	    /**
659	     * 组装升级查询视图：current 为该事件当前（唯一）升级记录，无则 null。
660	     */
661	    private EscalationHistoryView toEscalationHistory(Incident incident, List<Escalation> list) {
662	        List<EscalationView> views = list.stream().map(this::toEscalationView).toList();
663	        EscalationView current = views.isEmpty() ? null : views.get(views.size() - 1);
664	        return new EscalationHistoryView(incident.deadlineAt(), current, views);
665	    }
666	}
