137	     * 按事件与 actionKey 查询处置记录，用于幂等比对。
138	     */
139	    public Optional<IncidentAction> findAction(long incidentId, String actionKey) {
140	        List<IncidentAction> rows = jdbc.query(
141	                "SELECT * FROM incident_actions WHERE incident_id = ? AND action_key = ?",
142	                ACTION_MAPPER, incidentId, actionKey);
143	        return rows.stream().findFirst();
144	    }
