    Instant cutoff = req.cutoffAt().truncatedTo(MICROS);
    Incident incident = lockIncident(incidentKey);
    return runIdempotent(commandKey, "seal_create", hash(incidentKey, actor, cutoff.toString()),
            SealPackageView.class, () -> {
        requireCommander(incident, actor);
        if (incident.status() == CLOSED) throw illegalTransition("事件已关闭，不能新增封存包");
        Instant now = now();
        if (cutoff.isBefore(incident.createdAt())) throw badRequest with details;
        if (cutoff.isAfter(now)) throw badRequest with details;
        var last = seals.findLatest(incident.id());
        Instant lower = last.map(IncidentSealPackage::cutoffAt).orElse(incident.createdAt());
        if (last.isPresent() && !cutoff.isAfter(last.get().cutoffAt()))
            throw conflict("截至时刻必须晚于上一封存包...", details{actual, required, lastCutoff});
        // 同刻指令写入检查
        List<String> conflictKeys = incidents.listActions(incident.id()).stream()
            .filter(a -> a.occurredAt().equals(cutoff)).map(IncidentAction::actionKey).toList();
        if (!conflictKeys.isEmpty()) throw conflict("存在与截至时刻同刻的指令写入...", keys);
        ...
    });
}
