    @Test
    void appendix_mainFlowAndImmutability() {
        commanding("INC-S11", "alice");
        addAction("INC-S11", "alice", "A1", T0.plusSeconds(10));
        ((ControllableClock) clock).setInstant(T0.plusSeconds(100));
