        commanding("INC-S14", "alice");
        assertApiStatus(() -> sealService.sealDetail("INC-S14", 1), HttpStatus.NOT_FOUND);
        assertApiStatus(() -> sealService.sealHistory("INC-MISSING"), HttpStatus.NOT_FOUND);
    }
}

